import { Component, OnInit, OnDestroy } from '@angular/core';
import { Subscription } from 'rxjs';
import { ReceptionistService } from '../../../core/services/receptionist.service';
import { WebSocketService } from '../../../core/services/websocket.service';
import { Token, Priority } from '../../../core/models';

@Component({
  selector: 'app-queue-manage',
  templateUrl: './queue-manage.component.html'
})
export class QueueManageComponent implements OnInit, OnDestroy {

  queue: Token[] = [];
  loading = false;
  error = '';
  success = '';

  priorities: Priority[] = ['NORMAL', 'URGENT', 'EMERGENCY'];
  private wsSubs: Subscription[] = [];

  constructor(
    private receptionistService: ReceptionistService,
    private ws: WebSocketService
  ) {}

  ngOnInit(): void { this.loadQueue(); }

  loadQueue(): void {
    this.loading = true;
    this.receptionistService.getActiveQueue().subscribe({
      next: tokens => {
        this.queue = tokens;
        this.loading = false;
        // Subscribe to real-time updates for each doctor in queue
        const doctorIds = [...new Set(tokens.map(t => t.doctorId))];
        doctorIds.forEach(id => this.subscribeToDoctor(id));
      },
      error: () => { this.loading = false; }
    });
  }

  updatePriority(token: Token, newPriority: Priority): void {
    this.receptionistService.updatePriority(token.id, { priority: newPriority }).subscribe({
      next: updated => {
        const idx = this.queue.findIndex(t => t.id === updated.id);
        if (idx >= 0) this.queue[idx] = updated;
        this.success = `Priority updated to ${newPriority}`;
        setTimeout(() => this.success = '', 3000);
      },
      error: err => { this.error = err.error?.message ?? 'Failed to update priority.'; }
    });
  }

  removeToken(token: Token): void {
    if (!confirm(`Remove ${token.tokenNumber} from queue?`)) return;
    this.receptionistService.removeToken(token.id).subscribe({
      next: () => {
        this.queue = this.queue.filter(t => t.id !== token.id);
        this.success = 'Token removed from queue.';
        setTimeout(() => this.success = '', 3000);
      },
      error: err => { this.error = err.error?.message ?? 'Failed to remove token.'; }
    });
  }

  getPriorityClass(p: string): string {
    return `badge badge-${p.toLowerCase()}`;
  }

  getStatusClass(s: string): string {
    return `badge badge-${s.toLowerCase().replace('_', '-')}`;
  }

  private subscribeToDoctor(doctorId: number): void {
    const sub = this.ws.subscribeToQueue<Token[]>(doctorId).subscribe(updatedQueue => {
      // Merge updated doctor queue into the full queue
      this.queue = [
        ...this.queue.filter(t => t.doctorId !== doctorId),
        ...updatedQueue
      ];
    });
    this.wsSubs.push(sub);
  }

  ngOnDestroy(): void {
    this.wsSubs.forEach(s => s.unsubscribe());
  }
}
<div class="page-header">
  <h2>Queue Management</h2>
  <p>Manage active patient tokens. Priority updates are reflected in real time.</p>
</div>

<div *ngIf="success" class="alert alert-success">{{ success }}</div>
<div *ngIf="error"   class="alert alert-danger">{{ error }}</div>

<div class="card">
  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
    <strong>Active Queue ({{ queue.length }} tokens)</strong>
    <button class="btn btn-secondary" (click)="loadQueue()" [disabled]="loading">Refresh</button>
  </div>

  <table>
    <thead>
      <tr>
        <th>Token #</th>
        <th>Patient</th>
        <th>Doctor</th>
        <th>Dept</th>
        <th>Priority</th>
        <th>Status</th>
        <th>Position</th>
        <th>Change Priority</th>
        <th>Action</th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let token of queue">
        <td><strong>{{ token.tokenNumber }}</strong></td>
        <td>{{ token.patientName }}<br><small>{{ token.patientPhone }}</small></td>
        <td>{{ token.doctorName }}</td>
        <td>{{ token.departmentName }}</td>
        <td><span [class]="getPriorityClass(token.priority)">{{ token.priority }}</span></td>
        <td><span [class]="getStatusClass(token.status)">{{ token.status }}</span></td>
        <td>
          <span *ngIf="token.queuePosition > 0">{{ token.queuePosition }}</span>
          <span *ngIf="token.queuePosition === 0" style="color:#007bff;">In Progress</span>
        </td>
        <td>
          <select *ngIf="token.status === 'WAITING'"
            [value]="token.priority"
            (change)="updatePriority(token, $any($event.target).value)"
            style="padding:4px;border:1px solid #ced4da;border-radius:4px;font-size:13px;">
            <option *ngFor="let p of priorities" [value]="p">{{ p }}</option>
          </select>
          <span *ngIf="token.status !== 'WAITING'" style="color:#6c757d;font-size:12px;">—</span>
        </td>
        <td>
          <button *ngIf="token.status === 'WAITING'"
            class="btn btn-danger"
            style="font-size:12px;padding:4px 10px;"
            (click)="removeToken(token)">Remove</button>
        </td>
      </tr>
    </tbody>
  </table>

  <p *ngIf="!loading && queue.length === 0"
     style="text-align:center;color:#6c757d;padding:24px;">
    Queue is empty.
  </p>
</div>
